{
  "name": "HORIBA SpectrAcq3 光谱采集系统",
  "name_en": "HORIBA SpectrAcq3 Spectral Acquisition System",
  "manufacturer": "HORIBA Scientific",
  "description": "一套用于实验室光谱测量的光学采集系统，可与单色仪和 CCD 探测器等部件配合使用，完成仪器连接、设备识别与光谱数据采集准备，常用于科研中的光谱分析与测量实验。",
  "description_en": "An optical acquisition system for laboratory spectroscopy, used together with components such as monochromators and CCD detectors to support instrument connection, device discovery, and preparation for spectral data acquisition in research measurements.",
  "actions": [
    {
      "action_name": "auto-start",
      "description": "启动设备管理与通信会话。",
      "description_en": "Start device management and the communication session."
    },
    {
      "action_name": "auto-stop",
      "description": "停止设备管理与通信会话。",
      "description_en": "Stop device management and the communication session."
    },
    {
      "action_name": "auto-start_icl",
      "description": "启动 ICL 通信控制程序并建立与仪器的连接。",
      "description_en": "Start the ICL communication control program and establish connection to the instrument."
    },
    {
      "action_name": "auto-stop_icl",
      "description": "停止 ICL 通信并清理连接资源。",
      "description_en": "Stop ICL communication and clean up connection resources."
    },
    {
      "action_name": "auto-discover_devices",
      "description": "扫描并识别已连接的设备，如单色仪、CCD 和 SpectrAcq3 设备。",
      "description_en": "Scan for and identify connected devices such as monochromators, CCDs, and SpectrAcq3 units."
    }
  ],
  "tag_hints": [
    "spectroscopy",
    "spectral acquisition",
    "monochromator",
    "CCD detector",
    "optical measurement",
    "HORIBA Scientific"
  ]
}

